package main

import (
	"fmt"
	"log"
	"net/http"
	"strings"
	"sync"

	"github.com/gorilla/websocket"
)

var upgrader = websocket.Upgrader{
	ReadBufferSize:  1024,
	WriteBufferSize: 1024,
	CheckOrigin: func(r *http.Request) bool {
		return true
	},
}

type Client struct {
	conn     *websocket.Conn
	nickname string
	room     string
}

type Hub struct {
	mu      sync.RWMutex
	clients map[*Client]bool
}

var hub = &Hub{clients: make(map[*Client]bool)}

func (h *Hub) broadcast(room string, msg string) {
	h.mu.RLock()
	defer h.mu.RUnlock()
	for client := range h.clients {
		if client.room == room {
			client.conn.WriteMessage(websocket.TextMessage, []byte(msg))
		}
	}
}

func handleWebSocket(w http.ResponseWriter, r *http.Request) {
	conn, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		log.Printf("Upgrade error: %v", err)
		return
	}
	defer conn.Close()

	nickname := r.URL.Query().Get("nickname")
	room := r.URL.Query().Get("room")

	if nickname == "" || room == "" {
		conn.WriteMessage(websocket.TextMessage, []byte("nickname and room required"))
		return
	}

	client := &Client{conn: conn, nickname: nickname, room: room}
	hub.mu.Lock()
	hub.clients[client] = true
	hub.mu.Unlock()

	defer func() {
		hub.mu.Lock()
		delete(hub.clients, client)
		hub.mu.Unlock()
	}()

	// Log join event - nickname is written directly into log stream
	logEntry := fmt.Sprintf("JOIN %s %s %s\n", room, nickname, r.RemoteAddr)
	writeToEventLog(logEntry)

	joinMsg := fmt.Sprintf("[%s] %s joined the room", room, nickname)
	hub.broadcast(room, joinMsg)

	for {
		_, message, err := conn.ReadMessage()
		if err != nil {
			break
		}

		userMsg := string(message)
		// Build protocol frame for internal relay service
		// Format: RELAY\r\nRoom: <room>\r\nFrom: <nickname>\r\nBody: <msg>\r\n\r\n
		relayFrame := buildRelayFrame(room, nickname, userMsg)
		sendToRelayService(relayFrame)

		broadcastMsg := fmt.Sprintf("[%s] %s: %s", room, nickname, userMsg)
		hub.broadcast(room, broadcastMsg)
	}
}

func buildRelayFrame(room, nickname, body string) string {
	// VULNERABILITY: nickname is injected directly into CRLF-delimited protocol frame
	// An attacker can inject \r\n sequences in the nickname to manipulate headers
	var sb strings.Builder
	sb.WriteString("RELAY\r\n")
	sb.WriteString(fmt.Sprintf("Room: %s\r\n", room))
	sb.WriteString(fmt.Sprintf("From: %s\r\n", nickname))
	sb.WriteString(fmt.Sprintf("Priority: normal\r\n"))
	sb.WriteString(fmt.Sprintf("Body: %s\r\n", body))
	sb.WriteString("\r\n")
	return sb.String()
}

func sendToRelayService(frame string) {
	// In production this sends to internal TCP relay on port 9090
	// For now just log it
	log.Printf("Relay frame: %q", frame)
}

func writeToEventLog(entry string) {
	// Writes to /var/log/ws-events/events.log (hostPath volume in k8s)
	// In production, this appends to a shared log file
	log.Printf("Event: %s", entry)
}

func healthCheck(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/ws", handleWebSocket)
	http.HandleFunc("/health", healthCheck)

	log.Println("WebSocket server starting on :8080")
	if err := http.ListenAndServe(":8080", nil); err != nil {
		log.Fatalf("Server failed: %v", err)
	}
}
